package dev.lemon.lemon_emu.features.aiconfig

import android.content.Context
import dev.lemon.lemon_emu.R
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.booleanOrNull
import kotlinx.serialization.json.longOrNull

/**
 * The settings the AI game config may change, from res/raw/ai_settings_schema.json (generated by
 * .ci/ai-schema). Anything the server suggests is checked here again before it is written.
 */
@Serializable
data class AiSchema(
    val app: String,
    val schema_version: Int,
    val settings: List<Entry>
) {
    @Serializable
    data class Entry(
        val key: String,
        val tier: String,
        val type: String,
        val default: String? = null,
        val min: String? = null,
        val max: String? = null,
        val enum: List<EnumValue>? = null,
        val ui_title: String? = null,
        /** Name of the string resource the settings screens use as its title. */
        val ui_title_res: String? = null,
        val description: String? = null
    ) {
        val isRisky get() = tier == "risky"
        val isBool get() = type == "bool"
    }

    @Serializable
    data class EnumValue(val name: String, val value: Long)

    private val byKey by lazy { settings.associateBy { it.key } }

    fun entry(key: String): Entry? = byKey[key]

    /**
     * The text config.ini would store for [value] on [key], or null if the key is not in the
     * schema or the value does not fit it (wrong type, not one of the enum values, out of range).
     */
    fun normalize(key: String, value: JsonElement): String? {
        val entry = byKey[key] ?: return null
        val primitive = value as? JsonPrimitive ?: return null
        if (entry.isBool) {
            return primitive.booleanOrNull?.toString()
        }
        if (primitive.isString) return null
        val number = primitive.longOrNull ?: return null
        entry.enum?.let { values ->
            return if (values.any { it.value == number }) number.toString() else null
        }
        if (!isIntegral(entry.type)) return null
        entry.min?.toLongOrNull()?.let { if (number < it) return null }
        entry.max?.toLongOrNull()?.let { if (number > it) return null }
        if (number < 0 && entry.type.startsWith("u")) return null
        return number.toString()
    }

    /** How [stored] (a config.ini value) reads for a person: the enum name or the value itself. */
    fun describe(key: String, stored: String): String {
        val entry = byKey[key] ?: return stored
        val number = stored.toLongOrNull()
        return entry.enum?.firstOrNull { it.value == number }?.name ?: stored
    }

    private fun isIntegral(type: String) =
        type in setOf("u8", "u16", "u32", "u64", "s8", "s16", "s32", "s64", "int", "long")

    companion object {
        private val json = Json { ignoreUnknownKeys = true }

        @Volatile
        private var cached: AiSchema? = null

        fun load(context: Context): AiSchema = cached ?: synchronized(this) {
            cached ?: context.resources.openRawResource(R.raw.ai_settings_schema)
                .bufferedReader().use { json.decodeFromString(serializer(), it.readText()) }
                .also { cached = it }
        }
    }
}
